using Unity.Entities;
using UnityEngine;

namespace ToLive.Crisis
{
    /// <summary>A fortification spot (grey-box tower), generated by Tools > To Live. Raised (shown) when the district is dominated.</summary>
    [DisallowMultipleComponent]
    public class FortificationAuthoring : MonoBehaviour
    {
        public int Index;
        [Tooltip("Muzzle / beacon height above this object's position.")] public float TopHeight = 14f;

        class Baker : Baker<FortificationAuthoring>
        {
            public override void Bake(FortificationAuthoring a)
            {
                var e = GetEntity(TransformUsageFlags.Renderable);
                AddComponent(e, new Fortification { Index = a.Index, Top = a.transform.position + Vector3.up * a.TopHeight });
            }
        }
    }
}
